204		The measurements $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ and observables $\tilde{W}^j(\tilde{u})$ satisfy the following properties.
205		% The paper's statement also quantifies item 1 over j, but j does not occur
206		% in item 1; the vacuous quantifier is dropped here.
207		\begin{enumerate}
208			\item (\textbf{Consistency with points measurements}) For all $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
209			\[
210				\Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \simeq_{\delta_P^{\mathrm{AB}}} M^{(\mathrm{Point},W),u}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''}
211			\]
212			and
213			\[
214				\tilde{M}^{W,\mathrm{ind}_m(u)}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \simeq_{\delta_P^{\mathrm{BA}}} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot M^{(\mathrm{Point},W),u}_a\;,
215			\]
216			with the answer summation over $a \in \F_q$.
217			\item (\textbf{Self-consistency}) For all $W \in \{X,Z\}$ and $j \in \{0,\ldots,t-1\}$, on average over uniformly random $\tilde{u} \in \F_q^{M}$,
218			\[
219				\tilde{W}^j(\tilde{u}) \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \approx_{\delta_P^{\mathrm{obs}}} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{W}^j(\tilde{u})\;.
220			\]
221		\end{enumerate}
222	\end{lemma}
